    async function initializeMintPanel(panel) {
        installMintStyle();
        buildMintStudio(panel);
        installMintRuntimeControls(panel);
        imagePlan=normalizeImagePlan(imagePlan);
        await renderImagePlan(panel);
        panel.addEventListener('click', e => {
            const control = e.target.closest('button,summary,input[type=checkbox],select,input[type=file]');
            if (!control || control.disabled) return;
            control.classList.remove('mint-tap'); void control.offsetWidth; control.classList.add('mint-tap');
            if(!uiPrefs.showClickNotices)return;
            if (control.tagName === 'SUMMARY') showCapsule(control.parentElement.open ? '正在收起选项' : '正在展开选项');
            else if (control.type === 'checkbox') showCapsule(control.checked ? '已勾选' : '已取消勾选');
            else if (control.type === 'file') showCapsule('请选择要导入的图片');
        }, true);
        uiPrefs=normalizeUiPrefs(uiPrefs);
        themePrefs=normalizeThemePrefs(themePrefs);
        await initializeMintStudio(panel);
        panel.querySelector('#mint-gallery-url').value = galleryConfig.baseUrl || '';
        panel.querySelector('#mint-gallery-token').value = galleryConfig.token || '';
        const requestOrigin=window.origin||window.location.origin;
        panel.querySelector('#mint-origin').textContent=window.__XUBAI_PREVIEW__?'这是界面预览；请在正式酒馆内查看实际 Origin。':`当前请求 Origin：${requestOrigin}（服务器允许来源需与此一致）`;
        applyMintTheme(); clearInterval(themeTimer); themeTimer = setInterval(applyMintTheme, 15000);
        on(panel.querySelector('#mint-gallery-connect'), 'click', async () => {
            const config = { baseUrl: normalizeGalleryUrl(panel.querySelector('#mint-gallery-url').value.trim()), token: panel.querySelector('#mint-gallery-token').value.trim() };
            if (!config.token) throw new Error('请填写图库专用管理密钥');
            const data = await galleryRequest('/api/images', {}, config);
            if (!Array.isArray(data.images)) throw new Error('该地址不是兼容的图库服务');
            galleryConfig = config; remoteImages = data.images; remoteGalleryLoaded = true;galleryCheckedAt=Date.now();galleryConnectionNote='已连接';
            await saveConfig(GALLERY_CONFIG_KEY, config); await renderRemoteGallery(panel);
            panel.querySelector('#mint-usage').textContent = `已连接 · ${(data.used_bytes / 1048576).toFixed(1)} MB / ${(data.quota_bytes / 1073741824).toFixed(1)} GB`;
            if (session) await renderPlaceholders(panel);
            toast('图库连接成功，配置已保存。到图库页就能管理图片。', 'success');
        });
        on(panel.querySelector('#mint-gallery-upload'), 'change', async e => {
            const file = e.target.files[0]; if (!file) return;
            try { await uploadRemoteImage(file); await renderRemoteGallery(panel); if (session) await renderPlaceholders(panel); toast('图片已上传到服务器', 'success'); }
            finally { e.target.value = ''; }
        });
        on(panel.querySelector('#mint-gallery-forget'), 'click', async () => {
            if (!(await mintConfirm('清除本机保存的图库连接配置？服务器文件会保留。'))) return;
            await deleteConfig(GALLERY_CONFIG_KEY); galleryConfig = { baseUrl:'', token:'' }; remoteImages = []; remoteGalleryLoaded = false;
            panel.querySelector('#mint-gallery-url').value = ''; panel.querySelector('#mint-gallery-token').value = '';
            galleryConnectionNote='';galleryCheckedAt=0;panel.querySelector('#mint-usage').textContent = ''; await renderRemoteGallery(panel);
            if (session) await renderPlaceholders(panel);
            toast('已清除本机图库配置', 'success');
        });
        on(panel.querySelector('#mint-cancel-generation'), 'click', () => {
            if (!generationBusy) return toast('当前没有生成任务');
            generationEpoch++; generationController?.abort();
            setStatusIfOpen('已取消接收结果。酒馆连接的远端生成可能仍会继续计费。');
            toast('已取消接收本次生成结果', 'info');
        });
        await renderRemoteGallery(panel); syncGenerationUI();updateConnectionOverview(panel);
        void refreshSavedGallery();
    }
    async function persistSessionImages() {
        if (!session?.historyId) return;
        await addHistory({ ...session, id: session.historyId, ts: session.historyTs });
    }
    function syncGenerationUI() {
        const panel = targetDoc.getElementById('aibar-panel'); if (!panel) return;
        for (const id of ['ab-generate', 'ab-revise-btn', 'ab-variant-btn']) {
            const button = panel.querySelector('#' + id); if (!button) continue;
            button.disabled = generationBusy;
            if (generationBusy) { button.dataset.generationLock = '1'; button.setAttribute('aria-busy', 'true');if(!button.querySelector('.mint-loading-ring'))button.prepend(mintSpinner()); }
            else { delete button.dataset.generationLock; button.removeAttribute('aria-busy');button.querySelector('.mint-loading-ring')?.remove(); }
        }
        panel.querySelector('#mint-cancel-generation').hidden = !generationBusy;
        if (generationBusy) setStatusIfOpen('正在生成，关闭面板也会继续。');
    }
    function stripEmbeddedData(text) {
        return String(text || '').replace(/data:[^\s"'<>)]*;base64,[A-Za-z0-9+/=\r\n]+/gi, '{{IMG:removed_inline_asset}}');
    }
    async function receiveGeneration(promise, signal) {
        let timer, abort;
        const stop = new Promise((_, reject) => {
            abort = () => reject(new Error('已取消接收生成结果'));
            if (signal.aborted) return abort();
            signal.addEventListener('abort', abort, { once: true });
            timer = setTimeout(() => { generationController?.abort(); reject(new Error('生成等待超过 4 分钟')); }, 240000);
        });
        try { return await Promise.race([promise, stop]); }
        finally { clearTimeout(timer); signal.removeEventListener('abort', abort); }
    }
    async function modelFetch(url, options = {}) {
        const controller = generationController || new AbortController();
        const timer = setTimeout(() => controller.abort(), 240000);
        try { return await fetch(url, { ...options, signal: controller.signal }); }
        catch (e) { if (e.name === 'AbortError') throw new Error('生成已取消或请求超时'); throw e; }
        finally { clearTimeout(timer); }
    }
    function apiEndpoint(base, suffix) {
        const clean = base.replace(/\/+$/, '').replace(/\/(chat\/completions|models|messages)$/, '');
        return clean + (/\/v\d+(?:beta\d*)?$/.test(clean) ? '' : '/v1') + '/' + suffix;
    }

