    function switchMintPage(panel, page, announce = true) {
        if (!['create','gallery','history','settings'].includes(page)) return;
        const scroll = panel.querySelector('#mint-scroll');
        pageScroll.set(currentPage, scroll.scrollTop); currentPage = page;
        panel.querySelectorAll('[data-mint-page]').forEach(section => { section.hidden = section.dataset.mintPage !== page; });
        panel.querySelectorAll('[data-page]').forEach(button => { button.setAttribute('aria-selected',String(button.dataset.page === page)); button.tabIndex = button.dataset.page === page ? 0 : -1; });
        scroll.scrollTop = pageScroll.get(page) || 0;
        if(page==='gallery'){renderRemoteGallery(panel).catch(e=>toast(e.message,'error'));renderImagePlan(panel).catch(e=>toast(e.message,'error'));}
        if(page==='settings')updateConnectionOverview(panel);
        if (page === 'history') renderHistory(panel).catch(e => toast(e.message,'error'));
        if (announce && uiPrefs.showPageNotices) showCapsule(({create:'回到创作台',gallery:'打开图片收藏室',history:'打开灵感存档',settings:'打开设置'})[page]);
    }
    function updateConnectionLabel(panel) {
        const source = panel.querySelector('#ab-source'); const label = panel.querySelector('#mint-source-label');
        if (label) label.textContent = source.value === 'custom' ? '当前连接 · ' + (panel.querySelector('#ab-config-select').value || '请到设置选择 API') : '当前连接 · 酒馆已选模型';
    }
    function bindOtomePanel(panel) {
        panel.querySelectorAll('[data-page]').forEach(button => on(button,'click',()=>switchMintPage(panel,button.dataset.page)));
        panel.querySelectorAll('[data-go]').forEach(button => on(button,'click',()=>{
            switchMintPage(panel,button.dataset.go);
            if (button.textContent.includes('字体')) { panel.querySelector('#ab-font-details').open=true; panel.querySelector('#ab-font-details').scrollIntoView({block:'start',behavior:'smooth'}); }
        }));
        panel.querySelector('#mint-tabs').addEventListener('keydown',e=>{
            if (!['ArrowLeft','ArrowRight','Home','End'].includes(e.key)) return;
            e.preventDefault(); const pages=['create','gallery','history','settings']; const at=pages.indexOf(currentPage);
            const index=e.key==='Home'?0:e.key==='End'?3:(at+(e.key==='ArrowRight'?1:3))%4;
            switchMintPage(panel,pages[index]);panel.querySelector('#mint-tab-'+pages[index]).focus();
        });
        panel.querySelectorAll('[data-prompt]').forEach(button=>on(button,'click',()=>{
            const input=panel.querySelector('#ab-desc');input.value=[input.value.trim(),button.dataset.prompt].filter(Boolean).join('，');input.focus();showCapsule('已把风格词添进描述');
        }));
        const pet=()=>{
            const now=Date.now();avatarTapTimes=avatarTapTimes.filter(t=>now-t<5000);avatarTapTimes.push(now);
            if (avatarTapTimes.length>=5) { avatarTapTimes=[];showCapsule(['发现了？这里住着一只没有工资的程序员。','汪。……等等，串台了。我是写代码的那个小白。','银白头发不是加班造成的，原装就是这样。','你负责冒出想法，我负责把小玩意做出来。'][Math.floor(Math.random()*4)],'egg'); }
            else showCapsule('摸到了，小序收到。');
        };
        on(panel.querySelector('#mint-header-avatar'),'click',pet);on(panel.querySelector('#mint-hero-avatar'),'click',pet);
        on(panel.querySelector('#mint-demo-success'),'click',()=>showCapsule('做好了，快看看。这次可以摸一下头吗？','success'));
        on(panel.querySelector('#mint-demo-error'),'click',()=>showCapsule('这是报错样式演示，没有发生真实故障。线索会显示在这里，并且可以复制。','error'));
        on(panel.querySelector('#mint-gallery-refresh'),'click',async()=>{
            const data=await refreshSavedGallery(true);if(data)toast('图库已刷新','success');else if(galleryConnectionNote.startsWith('自动连接未完成'))throw new Error(galleryConnectionNote);
        });
        on(panel.querySelector('#mint-gallery-search'),'input',()=>renderRemoteGallery(panel));
        panel.addEventListener('change',()=>updateConnectionLabel(panel));
        bindThemeControls(panel);
        bindUiPrefs(panel);
        switchMintPage(panel,currentPage,false);updateConnectionLabel(panel);
    }
    function mintConfirm(message) {
        if (activeConfirmation) return Promise.resolve(false);
        return new Promise(resolve=>{
            const overlay=targetDoc.createElement('div');overlay.id='mint-confirm';overlay.dataset.theme=isDayTime()?'day':'night';
            overlay.innerHTML=`<div class="mint-confirm-card" role="dialog" aria-modal="true" aria-labelledby="mint-confirm-title"><img src="${MINT_DAY_AVATAR}" alt="小序"><h3 id="mint-confirm-title">确认一下这件事</h3><p></p><div class="mint-row"><button data-answer="no">先等等</button><button data-answer="yes">确认</button></div></div>`;
            overlay.querySelector('p').textContent=message;
            const previous=targetDoc.activeElement;
            const finish=value=>{targetDoc.removeEventListener('keydown',keyboard,true);overlay.remove();activeConfirmation=null;previous?.focus?.();resolve(value);};
            const keyboard=e=>{
                if(e.key==='Escape'){e.preventDefault();finish(false);}
                else if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button')];e.preventDefault();buttons[targetDoc.activeElement===buttons[0]?1:0].focus();}
            };
            activeConfirmation=()=>finish(false);targetDoc.body.appendChild(overlay);
            overlay.querySelector('[data-answer=no]').addEventListener('click',()=>finish(false),{once:true});
            overlay.querySelector('[data-answer=yes]').addEventListener('click',()=>finish(true),{once:true});
            overlay.addEventListener('click',e=>{if(e.target===overlay)finish(false);});
            targetDoc.addEventListener('keydown',keyboard,true);overlay.querySelector('[data-answer=no]').focus();
        });
    }
    async function copyMintMessage(text) {
        try { await targetWindow.navigator.clipboard.writeText(text); showCapsule('错误信息已复制'); }
        catch { const area=targetDoc.createElement('textarea');area.value=text;targetDoc.body.appendChild(area);area.select();const ok=targetDoc.execCommand?.('copy');area.remove();if(ok)showCapsule('错误信息已复制');else showCapsule('复制失败，请长按提示内容复制','warning'); }
    }

    const UI_PREFS_KEY='__mint_ui__';
    const DEFAULT_UI_PREFS={showPageNotices:false,showClickNotices:false,showDecorations:true};
    let uiPrefs={...DEFAULT_UI_PREFS};
    const MINT_DECORATIONS={gallery:'data:image/webp;base64,',history:'data:image/webp;base64,',settings:'data:image/webp;base64,'};
    function normalizeUiPrefs(value) {
        const result={...DEFAULT_UI_PREFS};
        for(const key of Object.keys(result))if(typeof value?.[key]==='boolean')result[key]=value[key];
        return result;
    }
    function placeFeedbackAboveTabs(viewHeight,navTop,gap=12) { return Math.max(18,Math.ceil(viewHeight-navTop+gap)); }
    function positionMintFeedback() {
        const box=targetDoc.getElementById('mint-feedback');if(!box)return;
        const panel=targetDoc.getElementById('aibar-panel');
        if(mountMintFeedback(box)){box.style.removeProperty('bottom');box.style.removeProperty('left');box.style.removeProperty('max-height');return;}
        const nav=panel?.querySelector('#mint-tabs');
        if(!nav||!nav.getClientRects().length){box.style.removeProperty('bottom');box.style.removeProperty('left');box.style.removeProperty('max-height');return;}
        const rect=nav.getBoundingClientRect();const viewHeight=targetWindow.innerHeight;
        box.style.bottom=placeFeedbackAboveTabs(viewHeight,rect.top)+'px';
        box.style.left=(rect.left+rect.width/2)+'px';
        const visualTop=targetWindow.visualViewport?.offsetTop||0;
        box.style.maxHeight=Math.max(60,rect.top-visualTop-24)+'px';
    }
    function syncUiPrefs(panel) {
        panel.dataset.decorations=uiPrefs.showDecorations?'on':'off';
        const fields={'mint-page-notices':'showPageNotices','mint-click-notices':'showClickNotices','mint-decoration-toggle':'showDecorations'};
        for(const [id,key]of Object.entries(fields)){const input=panel.querySelector('#'+id);if(input)input.checked=uiPrefs[key];}
    }
    function bindUiPrefs(panel) {
        syncUiPrefs(panel);
        const fields={'mint-page-notices':'showPageNotices','mint-click-notices':'showClickNotices','mint-decoration-toggle':'showDecorations'};
        for(const [id,key]of Object.entries(fields))on(panel.querySelector('#'+id),'change',async e=>{
            const next={...uiPrefs,[key]:e.target.checked};
            try{await saveConfig(UI_PREFS_KEY,next);uiPrefs=next;syncUiPrefs(panel);toast('界面偏好已保存','success');}
            catch(error){syncUiPrefs(panel);throw error;}
        });
        positionMintFeedback();
    }
    function mintEmptyState(kind,title,message) {
        return `<div class="mint-card mint-empty"><img class="mint-decoration mint-empty-mascot" src="${MINT_DECORATIONS[kind]||MINT_DAY_AVATAR}" alt=""><b>${esc(title)}</b><p class="mint-muted">${esc(message)}</p></div>`;
    }

    function generateUUID() {
        if (globalThis.crypto?.randomUUID) return crypto.randomUUID();
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
            const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

    let dbOpening=null;
    function initDB() {
        if(db)return Promise.resolve(db);
        if(dbOpening)return dbOpening;
        dbOpening=new Promise((resolve, reject) => {
            if (db) return resolve(db);
            const req = indexedDB.open(DB_NAME, 6);
            req.onupgradeneeded = e => {
                const _db = e.target.result;
                if (!_db.objectStoreNames.contains(STORE)) _db.createObjectStore(STORE);
                if (!_db.objectStoreNames.contains('groups')) _db.createObjectStore('groups');
                if (!_db.objectStoreNames.contains('urlmap')) _db.createObjectStore('urlmap');
                if (!_db.objectStoreNames.contains(HISTORY_STORE)) _db.createObjectStore(HISTORY_STORE);
                if (!_db.objectStoreNames.contains(CONFIG_STORE)) _db.createObjectStore(CONFIG_STORE);
                if (!_db.objectStoreNames.contains(FONT_STORE)) _db.createObjectStore(FONT_STORE);
            };
            req.onsuccess = e => { if(destroyed){e.target.result.close();reject(new Error('脚本已关闭'));return;} db = e.target.result; db.onversionchange = () => { db.close(); db = null; }; resolve(db); };
            req.onblocked = () => reject(new Error('图库升级被其他页面阻塞，请关闭重复酒馆页面后重试'));
            req.onerror = () => reject(new Error('本地数据库初始化失败'));
        }).finally(()=>{dbOpening=null;});
        return dbOpening;
    }

    function blobToDataUri(blob) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    }

    async function getCurrentCharacterId() {
        try { const p = await Promise.resolve(getCharAvatarPath()); if (p) return p; } catch (e) {}
        try { const n = await Promise.resolve(getCurrentCharacterName()); if (n) return n; } catch (e) {}
        return null;
    }

    // ================= 共享图库读写 =================
    function refreshCacheFor(key, blob) {
        if (urlCache.has(key)) URL.revokeObjectURL(urlCache.get(key));
        urlCache.set(key, URL.createObjectURL(blob));
    }
    async function saveImage(key, blob) {
        await initDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE, 'readwrite');
            tx.onerror = () => reject(tx.error || new Error('本地数据库操作失败'));
            tx.onabort = () => reject(tx.error || new Error('本地数据库操作已取消'));
            tx.objectStore(STORE).put(blob, key);
            tx.oncomplete = () => { refreshCacheFor(key, blob); resolve(); };
            tx.onerror = () => reject(tx.error || new Error('图片保存失败'));
            tx.onabort = () => reject(tx.error || new Error('图片保存已取消'));
        });
    }
    async function getImageBlob(key) {
        await initDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE, 'readonly');
            tx.onerror = () => reject(tx.error || new Error('本地数据库操作失败'));
            tx.onabort = () => reject(tx.error || new Error('本地数据库操作已取消'));
            tx.objectStore(STORE).get(key).onsuccess = e => resolve(e.target.result || null);
        });
    }
    async function listImageKeys() {
        await initDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE, 'readonly');
            tx.onerror = () => reject(tx.error || new Error('本地数据库操作失败'));
            tx.onabort = () => reject(tx.error || new Error('本地数据库操作已取消'));
            const req = tx.objectStore(STORE).getAllKeys();
            req.onsuccess = () => resolve((req.result || []).filter(k => k !== '__ball_icon__'));
        });
    }
    async function preloadAllImages() {
        await initDB();
        const tx = db.transaction(STORE, 'readonly');
        const store = tx.objectStore(STORE);
        const keysReq = store.getAllKeys();
        const valsReq = store.getAll();
        return new Promise((resolve, reject) => {
            tx.onerror = () => reject(tx.error || new Error('本地图库读取失败'));
            tx.onabort = () => reject(tx.error || new Error('本地图库读取已取消'));
            tx.oncomplete = () => {
                const keys = keysReq.result || [];
                const vals = valsReq.result || [];
                keys.forEach((k, i) => { if (vals[i]) refreshCacheFor(k, vals[i]); });
                resolve();
            };
        });
    }

